     "time": "10-21 17:50",
     "ts": 1792576254,
     "summary": "中国能建华北院主编的国家标准《可再生能源电解水制氢系统技术要求》（GB/T 48329-2026）正式发布，2027年1月1日起实施。该标准由华北院联合十余家单位编制，涵盖装置、储氢、供配电、安全、运行测试等全环节，适用于风光电并网及离网制氢系统。华北院依托多项示范项目与科研攻关，构建“基础研究—工程示范—标准输出”全链条体系，填补国内专项标准空白，支撑“双碳”目标实现。",
     "source": "国际能源网",
     "agenda_layer": "media",
